/*
 * Generated by Circuit OS — Template: project (Composition M2)
 * Intent: Room monitor: an Uno reads a DHT22, sounds a buzzer above 30 C, and lights a status LED
 * Board: Arduino Uno R3
 * Circuit ID: f42051c2-d905-55ee-b9b1-4b5f4fb25c3e
 *
 * Blocks:
 *   climate: temperature_humidity_sensor on D2 (dht22_node@0.3.0)
 *   alarm: load_switch on D8 (load_switch@0.1.0)
 *   status: led_indicator on D13 (led_indicator@0.4.0)
 *
 * Behaviour, evaluated in order after every sensor reading (later rules win):
 *   1. when climate temperature_c > 30 C: alarm blink, else alarm off
 *   2. always: status heartbeat
 */

#include <DHT.h>

enum Mode { MODE_OFF, MODE_ON, MODE_BLINK, MODE_HEARTBEAT };

// climate: DHT22 on D2
DHT dht_climate(2, DHT22);
float climate_temperature_c = NAN;
float climate_humidity_pct = NAN;
bool climate_ok = false;

// Outputs: alarm on D8, status on D13
const int OUT_PINS[2] = { 8, 13 };
const char* const OUT_NAMES[2] = { "alarm", "status" };
Mode out_mode[2];

const unsigned long READ_INTERVAL_MS = 2000;   // the DHT22 cannot be read faster
unsigned long last_read = 0;
bool first_read = true;

const char* mode_name(Mode m) {
  switch (m) {
    case MODE_ON: return "on";
    case MODE_BLINK: return "blink";
    case MODE_HEARTBEAT: return "heartbeat";
    default: return "off";
  }
}

void evaluate_rules() {
  Mode next[2];
  for (int i = 0; i < 2; i++) next[i] = MODE_OFF;
  // 1. when climate temperature_c > 30 C: alarm blink, else alarm off
  if (climate_ok && (climate_temperature_c > 30.0f)) {
    next[0] = MODE_BLINK;
  } else {
    next[0] = MODE_OFF;
  }
  // 2. always: status heartbeat
  next[1] = MODE_HEARTBEAT;
  for (int i = 0; i < 2; i++) {
    if (next[i] != out_mode[i]) {
      Serial.print("[OUT] ");
      Serial.print(OUT_NAMES[i]);
      Serial.print(" -> ");
      Serial.println(mode_name(next[i]));
    }
    out_mode[i] = next[i];
  }
}

void read_sensors() {
  climate_humidity_pct = dht_climate.readHumidity();
  climate_temperature_c = dht_climate.readTemperature();
  climate_ok = !(isnan(climate_humidity_pct) || isnan(climate_temperature_c));
  if (climate_ok) {
    Serial.print("[climate] ");
    Serial.print(climate_temperature_c);
    Serial.print(" C  ");
    Serial.print(climate_humidity_pct);
    Serial.println(" %");
  } else {
    Serial.println("[climate] read failed: check wiring and the pull-up on D2");
  }
}

void setup() {
  Serial.begin(115200);
  dht_climate.begin();
  for (int i = 0; i < 2; i++) {
    pinMode(OUT_PINS[i], OUTPUT);
    digitalWrite(OUT_PINS[i], LOW);
    out_mode[i] = MODE_OFF;
  }
  Serial.println("[CircuitOS] Room monitor: an Uno reads a DHT22, sounds a buzzer above 30 C, and lights a status LED");
}

void loop() {
  unsigned long now = millis();
  if (first_read || now - last_read >= READ_INTERVAL_MS) {
    first_read = false;
    last_read = now;
    read_sensors();
    evaluate_rules();
  }
  for (int i = 0; i < 2; i++) {
    bool level = false;
    switch (out_mode[i]) {
      case MODE_ON: level = true; break;
      case MODE_BLINK: level = (now / 250) % 2 == 0; break;
      case MODE_HEARTBEAT: level = (now % 1000) < 100; break;
      default: level = false;
    }
    digitalWrite(OUT_PINS[i], level ? HIGH : LOW);
  }
}

